// Build the OpenAI vision request.
// The photo is already in Supabase Storage, so we send the URL rather than
// base64 - no binary handling, no filesystem-mode problems.
const cfg = $('Load Config').first().json;
const up  = $('Upload to Storage').first().json;

const key = up?.Key ?? up?.key ?? up?.path ?? null;
const photoUrl = key
  ? `${cfg.supabase_url}/storage/v1/object/public/${key}`
  : null;

// What the resident said they were reporting, so the model can judge whether
// the photo actually shows it rather than judging the photo in isolation.
const reported = (cfg.text || '').slice(0, 500);

const prompt = [
  'You are checking whether a photo sent by a resident is good enough for a',
  'property manager to act on WITHOUT asking follow-up questions.',
  '',
  reported ? `The resident said: "${reported}"` : 'No accompanying text was sent.',
  '',
  'Judge strictly. A photo is only USABLE if a manager could look at it and',
  'see what is wrong and where. Reject it if it is too dark, blurred, too far',
  'away, too close to tell what the object is, shows something unrelated, or',
  'shows the general area without showing the actual fault.',
  '',
  'Reply with JSON only, no prose, in this exact shape:',
  '{',
  '  "verdict": "USABLE" | "REJECT",',
  '  "reason": "<if REJECT, one short plain-English sentence a resident would',
  '             understand, describing what is wrong with the photo and what',
  '             to photograph instead. Empty string if USABLE.>",',
  '  "shows": "<what is visibly wrong, under 60 words. Empty if REJECT.>",',
  '  "trade": "plumbing|electrical|appliance|structural|damp_mould|pest|cleaning|security|internet|other",',
  '  "safety_risk": true | false',
  '}'
].join(' ');

const payload = {
  model: 'gpt-4o',
  max_tokens: 400,
  response_format: { type: 'json_object' },
  messages: [{
    role: 'user',
    content: [
      { type: 'text', text: prompt },
      { type: 'image_url', image_url: { url: photoUrl, detail: 'high' } }
    ]
  }]
};

return [{ json: { photo_url: photoUrl, body: JSON.stringify(payload) } }];

// Merge resident context, config and any photo into one agent input.
const env = $('Load Config').first().json;
const identity = $('Resolve Identity').first().json;
const rows = Array.isArray(identity) ? identity : [identity];
const row = rows[0];

// --- Photo ---------------------------------------------------------------
// The photo's existence must NOT depend on the vision call succeeding. If the
// upload worked, the agent is told a photo arrived even when analysis failed.
let photoUrl = null;
try {
  photoUrl = $('Build Vision Request').first().json.photo_url ?? null;
} catch (e) { /* no photo this turn */ }
if (!photoUrl) {
  try {
    const up = $('Upload to Storage').first().json;
    const key = up?.Key ?? up?.key ?? up?.path ?? null;
    if (key) photoUrl = `${env.supabase_url}/storage/v1/object/public/${key}`;
  } catch (e) { /* no photo this turn */ }
}

let vision = null;
try {
  vision = $('Analyse Image').first().json?.choices?.[0]?.message?.content ?? null;
} catch (e) { /* analysis failed or did not run */ }

// Photo verdict. The vision model returns JSON: USABLE or REJECT with a
// plain-English reason. A rejected photo is NOT accepted - the agent asks for
// another one. The only way past this is an explicit refusal by the resident,
// which is handled in the prompt, not here.
let imageNote = '';
if (photoUrl) {
  let v = null;
  try { v = JSON.parse(vision); } catch (e) { v = null; }

  if (v && v.verdict === 'REJECT') {
    imageNote = `\n\n[PHOTO_REJECTED. Stored at: ${photoUrl}. `
      + `Reason: ${v.reason || 'the photo does not clearly show the reported problem'}. `
      + `This photo is NOT acceptable. Tell the resident warmly what to photograph `
      + `instead, using that reason, and wait for another picture. Do NOT create a `
      + `ticket yet. Do NOT set photo_status to "provided".]`;
  } else if (v && v.verdict === 'USABLE') {
    imageNote = `\n\n[PHOTO_ACCEPTED. Stored at: ${photoUrl}. `
      + `What it shows: ${v.shows || 'the reported problem'}. `
      + `Likely trade: ${v.trade || 'unknown'}. `
      + `Safety risk visible: ${v.safety_risk ? 'YES' : 'no'}. `
      + `Set photo_status to "provided" and use this URL as photo_url.]`;
  } else if (vision) {
    // Model replied but not in the expected shape. Treat as accepted rather
    // than blocking the resident on a parsing problem of ours.
    imageNote = `\n\n[PHOTO_ACCEPTED. Stored at: ${photoUrl}. Notes: ${vision}]`;
  } else {
    imageNote = `\n\n[PHOTO_ACCEPTED. Stored at: ${photoUrl}. It could not be `
      + `analysed automatically, but it HAS been received. Do not tell the resident `
      + `you cannot see it and do not ask for another one.]`;
  }
}

const resident = row?.residents ?? {};
const unit = resident?.units ?? {};
const isRegistered = Boolean(resident?.id);

const identityBlock = isRegistered
  ? [
      `Resident: ${resident.full_name}`,
      `Unit: ${unit.label}`,
      `Channel: ${env.channel}`,
      '',
      'This person is already registered. Never ask who they are or which unit they live in. You already know.',
    ].join('\n')
  : [
      `Channel: ${env.channel}`,
      '',
      'This person is NOT registered yet. Do not turn them away.',
      'Before you can create a ticket you must register them:',
      '1. Help with their question first if the knowledge base answers it. A knowledge base answer needs no registration.',
      '2. If they are reporting an issue, ask in ONE message for their full name and their unit (for example "Flat 12, Hawthorn House").',
      '3. Call list_units if they are unsure or give a unit label that is rejected, and offer them the real options.',
      '4. Call register_resident with their name and unit label. It returns resident_id and unit_id.',
      '5. Pass those two values to create_ticket when you eventually create the ticket.',
      'Then carry on with the normal interview. Do not re-ask for their name once registered.',
    ].join('\n');

// An image-only message has no text. Say so plainly rather than sending
// "(no text)", which reads to the model as an empty or broken message.
const body = env.text && env.text.trim()
  ? env.text
  : (photoUrl ? '(the resident sent a photo with no caption)' : '(no text)');

return [{
  json: {
    channel: env.channel,
    sessionKey: `${env.channel}:${env.channel_user_id}`,
    config: { estate_id: env.estate_id, estate_name: env.estate_name },
    is_registered: isRegistered,
    identity_block: identityBlock,
    resident: {
      id: resident.id ?? null,
      full_name: resident.full_name ?? null,
      unit_label: unit.label ?? null,
      unit_id: unit.id ?? null,
    },
    channel_user_id: env.channel_user_id,
    photo_url: photoUrl,
    agentInput: body + imageNote,
  }
}];

// Channel adapter: n8n hosted chat -> normalised envelope
// Persona demo links carry ?resident_ref=... so the grader is already a resident.
const body = $input.first().json;

const media = [];
const files = body.files ?? [];
for (const f of files) {
  if ((f.mimeType || '').startsWith('image/')) {
    media.push({ kind: 'image', ref: f.name, mime: f.mimeType });
  }
}

return [{
  json: {
    channel: 'web_chat',
    channel_user_id: body.metadata?.resident_ref || body.sessionId,
    text: body.chatInput ?? '',
    media,
    provider_message_id: body.sessionId,
    timestamp: new Date().toISOString(),
  }
}];

// Channel adapter: Telegram -> normalised envelope
const body = $input.first().json;
const msg = body.message ?? body.edited_message ?? body;

const media = [];
if (Array.isArray(msg.photo) && msg.photo.length) {
  // Telegram sends multiple sizes; the last entry is the largest
  const largest = msg.photo[msg.photo.length - 1];
  media.push({ kind: 'image', ref: largest.file_id, mime: 'image/jpeg' });
}

return [{
  json: {
    channel: 'telegram',
    channel_user_id: String(msg.from?.id ?? ''),
    text: msg.text ?? msg.caption ?? '',
    media,
    provider_message_id: String(msg.message_id ?? ''),
    timestamp: msg.date
      ? new Date(msg.date * 1000).toISOString()
      : new Date().toISOString(),
  }
}];

// Channel adapter: WhatsApp Business Cloud -> normalised envelope
const body = $input.first().json;
const value = body?.entry?.[0]?.changes?.[0]?.value ?? body;

// The "messages" webhook field also delivers delivery receipts (sent /
// delivered / read) and errors. Those are not resident messages. If we let
// them through, every reply we send generates more of them and the workflow
// answers itself forever. Drop anything that is not an inbound message.
if (value?.statuses || !Array.isArray(value?.messages) || value.messages.length === 0) {
  return [];
}

const msg = value.messages[0];

// Ignore message types we cannot handle rather than replying to them blankly.
const supported = ['text', 'image'];
if (msg.type && !supported.includes(msg.type)) {
  return [];
}

const media = [];
if (msg.image?.id) {
  media.push({ kind: 'image', ref: msg.image.id, mime: msg.image.mime_type || 'image/jpeg' });
}

const text = msg.text?.body ?? msg.image?.caption ?? '';
if (!text && media.length === 0) {
  return [];
}

return [{
  json: {
    channel: 'whatsapp',
    channel_user_id: msg.from || value?.contacts?.[0]?.wa_id || null,
    text,
    media,
    provider_message_id: msg.id ?? null,
    timestamp: msg.timestamp
      ? new Date(Number(msg.timestamp) * 1000).toISOString()
      : new Date().toISOString(),
  }
}];
